<script setup lang="ts">
import {computed,defineAsyncComponent,ref} from 'vue'
import {Mail,GitMerge,BookOpen,GraduationCap,Building2,Lightbulb,Coffee,MessageCircle,ArrowRight,Gift,CheckCheck,Clock3} from '@lucide/vue'
import type {ApiResult,Player,RoomState} from '../types'
import content from '../content.json'
import JointResearchPanel from './JointResearchPanel.vue'
import InstitutePanel from './InstitutePanel.vue'
import ScholarPortrait from './ScholarPortrait.vue'
const LabInterior=defineAsyncComponent(()=>import('./LabInterior.vue'))
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number;perform:(a:string,p?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const emit=defineEmits<{students:[]}>()
const section=ref('requests'),work=ref(props.player.portfolio.papers.at(-1)?.id||props.player.portfolio.patents.at(-1)?.id||''),route=ref('opensource'),note=ref(''),toPartner=ref(true),giftNote=ref(''),gift=ref('tea')
const tabs=[{id:'requests',name:'主动来信',icon:Mail},{id:'joint',name:'联合课题',icon:GitMerge},{id:'story',name:'连续故事',icon:BookOpen},{id:'alumni',name:'毕业与校友',icon:GraduationCap},{id:'institute',name:'教师与研究所',icon:Building2},{id:'transfer',name:'成果转化',icon:Lightbulb},{id:'room',name:'实验室实景',icon:Coffee}]
const requests=computed(()=>[...(props.player.living.requests||[])].sort((a,b)=>Number(['pending','invited'].includes(b.status))-Number(['pending','invited'].includes(a.status))||b.createdAt-a.createdAt)),pending=computed(()=>requests.value.filter(r=>r.status==='pending').length+props.state.incomingStudentRequests.length)
const partner=computed(()=>Object.values(props.state.players).find(p=>p.id!==props.player.id))
const story=computed(()=>props.player.living.story!),storyDef=computed(()=>content.living.stories[story.value.step])
const allWorks=computed(()=>[...props.player.portfolio.papers,...props.player.portfolio.patents].reverse())
const selectedRoute=computed(()=>content.living.routes.find(r=>r.id===route.value)!)
const personalNotes=computed(()=>Object.values(props.state.players).flatMap(p=>p.living.notes).filter(n=>n.from===props.player.id||n.to===props.player.id).sort((a,b)=>b.at-a.at))
const incomingGifts=computed(()=>props.player.living.gifts.filter(g=>g.to===props.player.id&&!g.openedAt))
const wait=(at:number)=>Math.max(0,Math.ceil((at-props.now)/60000))>=60?Math.ceil((at-props.now)/3600000)+' 小时':Math.max(0,Math.ceil((at-props.now)/60000))+' 分钟'
const date=(at:number)=>new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})
const careerName=(id:string|null)=>content.living.careers.find(c=>c.id===id)?.name||'去向待讨论'
function sendNote(){props.perform('living_note',{text:note.value,partner:toPartner.value});note.value=''}
</script>
<template><section class="living-panel"><header class="panel-heading"><div><span class="eyebrow">PEOPLE, PLACES & THE THINGS WE REMEMBER</span><h1>实验室生活</h1></div><Coffee :size="31"/></header><p class="living-lead">有些进展发生在论文里，有些发生在一起走过的路上。</p><nav class="living-tabs" aria-label="实验室生活栏目"><button v-for="t in tabs" :key="t.id" :class="{active:section===t.id}" @click="section=t.id"><component :is="t.icon" :size="16"/>{{ t.name }}<b v-if="t.id==='requests'&&pending">{{ pending }}</b></button></nav>
 <template v-if="section==='requests'"><div class="v8-heading"><MessageCircle :size="28"/><div><span class="small-label">THEY HAVE IDEAS OF THEIR OWN</span><h2>同学们也有自己的想法。</h2><p>聊聊、支持或说明目前安排，都能留下后续。请求不催回复，也不会因为离线而罚款。</p></div></div>
  <article v-for="r in state.incomingStudentRequests" :key="r.id" class="student-letter incoming"><span class="small-label">来自 {{ r.ownerName }} 组的跨组请求</span><h2>{{ r.title }}</h2><p>{{ r.body }}</p><p class="v8-muted">发起组已同意，接受后由发起方承担 40 支持费，双方同学联合采集四小时。</p><button class="primary" :disabled="busy" @click="perform('living_cross_respond',{id:r.id,accept:true})">同意两组同学合作</button><button class="secondary" :disabled="busy" @click="perform('living_cross_respond',{id:r.id,accept:false})">最近安排较满，先留个联系</button></article>
  <article v-for="c in state.livingCross.filter(c=>c.sides.some(x=>x.owner===player.id)&&c.status!=='completed')" :key="c.id" class="v8-note"><span class="small-label">两组学生 · 联合采集</span><h3>{{ c.title }}</h3><p>{{ c.status==='ready'?'采集已经完成，两组都可以留下资料与经历。':'同学们正在协作，预计 '+wait(c.dueAt)+' 后完成。' }}</p><button v-if="c.status==='ready'" class="primary" :disabled="busy" @click="perform('living_cross_claim',{id:c.id})"><CheckCheck :size="16"/>确认材料，双方记录经历</button></article>
  <article v-for="r in requests.slice(0,12)" :key="r.id" class="student-letter"><header><ScholarPortrait :seed="r.studentId" :size="48" :label="r.studentName+'头像'"/><div><b>{{ r.studentName }}给老师的留言</b><small>{{ date(r.createdAt) }}</small></div><span>{{ r.status==='pending'?'待讨论':r.status==='invited'?'等另一位老师':'已留回复' }}</span></header><h2>{{ r.title }}</h2><p class="letter-body">{{ r.body }}</p><div v-if="r.status==='pending'" class="letter-decisions"><button class="primary" :disabled="busy" @click="perform('living_request_reply',{id:r.id,choice:'approve'})">支持这个想法<ArrowRight :size="15"/></button><button class="secondary" :disabled="busy" @click="perform('living_request_reply',{id:r.id,choice:'discuss'})">先聊聊，把问题拆小</button><button class="text-button" :disabled="busy" @click="perform('living_request_reply',{id:r.id,choice:'decline'})">说明安排，暂时保留原计划</button></div><p v-else class="letter-reply">{{ r.result }}</p><button v-if="r.status==='invited'" class="text-button" :disabled="busy" @click="perform('living_request_withdraw',{id:r.id})">先撤回尚未开工的申请</button></article><p v-if="!requests.length&&!state.incomingStudentRequests.length" class="empty-note">第一封组内留言还在路上。有在读同学时，大约 {{ wait(player.living.nextRequestAt) }} 后会有人带着想法来讨论。</p><button class="text-button" @click="emit('students')">去看看同学最近的研究<ArrowRight :size="15"/></button>
 </template>
 <JointResearchPanel v-else-if="section==='joint'" :player="player" :state="state" :busy="busy" :now="now" :perform="perform"/>
 <template v-else-if="section==='story'"><header class="v8-heading"><BookOpen :size="29"/><div><span class="small-label">A STORY THAT REMEMBERS YOUR CHOICES</span><h2>从一封邀请，慢慢走到一个试点。</h2><p>前面的帮助、诚实与合作会留下记忆。下一封信可以晚些看，故事不会因你下线结束。</p></div></header><ol class="story-steps"><li v-for="(d,i) in content.living.stories" :key="d.title" :class="{done:i<story.step,current:i===story.step}"><i>{{ i<story.step?'✓':i+1 }}</i><span>{{ d.title }}</span></li></ol>
  <article v-if="storyDef" class="story-envelope"><span class="small-label">第 {{ story.step+1 }} 封 · {{ storyDef.sender }}</span><h2>{{ storyDef.title }}</h2><p v-if="story.step>0&&story.memory.declined" class="v8-muted">上次虽然没能到场，对方仍然从公开工作中认识了你。</p><p class="letter-body">{{ storyDef.body }}</p><p v-if="story.step===2&&story.memory.helped" class="remembered-note">许工程师还记得你上次认真整理的建议，愿意分担部分验证费。</p><p v-if="story.nextAt>now" class="v8-muted"><Clock3 :size="15"/>下一次交流约 {{ wait(story.nextAt) }} 后展开。</p><div class="story-choices"><button v-for="o in storyDef.options" :key="o.id" class="secondary" :disabled="busy||story.nextAt>now||player.funds<o.cost" @click="perform('living_story',{choice:o.id})">{{ o.text }}<ArrowRight :size="15"/></button></div></article><article v-else class="v8-note"><h2>这一段共同经历，已经留在园区。</h2><p>你的选择、合作伙伴与试点展板都会保留，后续还可以继续承接企业邀请和联合课题。</p></article><details v-if="story.history.length" class="v8-history"><summary>翻看走过的故事</summary><article v-for="h in [...story.history].reverse()" :key="h.id"><span class="small-label">{{ h.sender }} · {{ date(h.at) }}</span><h3>{{ h.title }}</h3><p>你的选择：{{ h.choice }}</p><p>{{ h.result }}</p></article></details></template>
 <template v-else-if="section==='alumni'"><header class="v8-heading"><GraduationCap :size="30"/><div><span class="small-label">THEY LEAVE THE CAMPUS, NOT THE STORY</span><h2>毕业以后，也会给你写信。</h2><p>去企业、继续研究、留校或尝试创业，都有不同的后续联系。原有简历、成果与共同经历会保留。</p></div></header><p v-if="!player.living.alumni.length" class="empty-note">还没有毕业生。先陪现在的同学把一个小目标做完整，未来的校友故事会从这里开始。</p><article v-for="a in player.living.alumni" :key="a.id" class="alumni-dossier"><header><ScholarPortrait :seed="a.studentId" :size="58" :label="a.name+'头像'"/><div><span class="small-label">{{ careerName(a.career) }}</span><h2>{{ a.name }}</h2><p>{{ a.topic }}</p></div></header><p v-if="a.career" class="v8-muted">{{ a.organization }} · {{ a.contact?'有一封新近况':'下一次联系约 '+wait(a.nextContactAt) }}</p><div v-else class="career-choices"><button v-for="c in content.living.careers" :key="c.id" class="secondary" :disabled="busy" @click="perform('living_alumni_career',{id:a.id,option:c.id})"><b>{{ c.name }}</b><small>{{ c.description }}</small></button></div><section v-if="a.contact" class="alumni-mail"><span class="small-label">来自毕业生的近况 · {{ date(a.contact.at) }}</span><p>{{ a.contact.body }}</p><button class="primary" :disabled="busy" @click="perform('living_alumni_reply',{id:a.id,choice:'notes'})">一起交流研究笔记</button><button class="secondary" :disabled="busy" @click="perform('living_alumni_reply',{id:a.id,choice:'introduce'})">看看引荐的合作或同学</button><button class="text-button" :disabled="busy" @click="perform('living_alumni_reply',{id:a.id,choice:'return'})">聊聊未来返校任职</button></section><p v-if="a.returnInterested&&!a.returnedAt" class="v8-success">这位校友愿意讨论回流任职。三级后可到“教师与研究所”正式邀请。</p><p v-for="(h,i) in a.history.slice(-4)" :key="i" class="v8-muted">{{ date(h.at) }} · {{ h.text }}</p></article></template>
 <InstitutePanel v-else-if="section==='institute'" :player="player" :state="state" :busy="busy" :perform="perform" @students="emit('students')"/>
 <template v-else-if="section==='transfer'"><header class="v8-heading"><Lightbulb :size="30"/><div><span class="small-label">LET THE RESULTS LEAVE THE PAGE</span><h2>成果还能继续生长。</h2><p>同一项已完成成果可以逐步走向开源、许可与校园示范，每条路线只安排一次。</p></div></header><form class="v8-form transfer-form" @submit.prevent="perform('living_transfer_start',{workId:work,route})"><label>选择已发表或授权的成果<select v-model="work"><option value="">先选择一项成果</option><option v-for="w in allWorks" :key="w.id" :value="w.id">{{ w.title }}</option></select></label><label>想让它走向哪里<select v-model="route"><option v-for="r in content.living.routes" :key="r.id" :value="r.id">{{ r.name }} · {{ r.cost }} 经费 · {{ r.hours }} 小时</option></select></label><p class="v8-muted">{{ selectedRoute.description }}<template v-if="route==='demo'">完成后共同实验室获得 600 建设经费，示范展台也会出现在校园和实验室实景里。</template></p><button class="primary" :disabled="busy||!work||player.funds<selectedRoute.cost||player.living.transfers.some(t=>t.workId===work&&t.route===route)||player.living.transfers.filter(t=>t.status==='working').length>=2">投入并安排这条路线<ArrowRight :size="15"/></button></form><article v-for="t in [...player.living.transfers].reverse()" :key="t.id" class="transfer-dossier"><span class="small-label">{{ content.living.routes.find(r=>r.id===t.route)?.name }} · {{ t.status==='working'?'推进中':t.status==='ready'?'可以确认成果':'已形成成果' }}</span><h3>{{ t.title }}</h3><p>已投入 {{ t.paid }} 经费<span v-if="t.status==='working'"> · 预计 {{ wait(t.dueAt) }} 后完成</span></p><button v-if="t.status==='ready'" class="primary" :disabled="busy" @click="perform('living_transfer_claim',{id:t.id})">确认转化成果</button><div v-if="t.status==='completed'&&t.route==='license'" class="license-income"><p>企业首款 300，持续许可 18/小时；当前待领 {{ Math.floor(t.buffer) }} / 600，累计到账 {{ t.totalIncome }}。</p><button class="secondary" :disabled="busy||t.buffer<1" @click="perform('living_transfer_claim',{id:t.id})">领取实际许可收入</button></div></article></template>
 <template v-else><header class="v8-heading"><Coffee :size="29"/><div><span class="small-label">TWO DESKS, MORE AND MORE STORIES</span><h2>把科研世界，慢慢住成自己的样子。</h2><p>科研资产、在读同学、教师、成果纪念和布置都会出现在各自区域。</p></div></header><LabInterior :state="state"/><div class="v8-summary-strip"><span>我的科研资产 <b>{{ player.assets.length }}</b></span><span>在组同学 <b>{{ player.students.filter(s=>!s.graduatedAt).length }}</b></span><span>纪念 <b>{{ player.living.memories.length }}</b></span></div><div class="memory-ribbon"><span v-for="m in player.living.memories" :key="m.id">{{ m.title }}</span></div><div class="section-title"><h2>给自己的实验室添一点东西</h2><span>布置只影响自己的区域</span></div><div class="decor-shop"><article v-for="d in content.living.decor" :key="d.id"><span>{{ d.kind==='plant'?'一小片绿意':d.kind==='desk'?'自己的配色':'工位以外的生活' }}</span><h3>{{ d.name }}</h3><p>{{ d.price }} 经费</p><button class="secondary" :disabled="busy||player.funds<d.price||player.living.decor.includes(d.id)" @click="perform('living_decor_buy',{option:d.id})">{{ player.living.decor.includes(d.id)?'已经在实验室里':'添进自己的区域' }}</button></article></div>
  <div class="section-title"><h2>留一句话，TA 晚点会看到</h2></div><form class="v8-form" @submit.prevent="sendNote"><label>桌边便签<textarea v-model="note" maxlength="120" rows="2" placeholder="例如：Reviewer 2 今天应该没上班。"/></label><label class="check-label"><input v-model="toPartner" type="checkbox" :disabled="!partner"/>放到 {{ partner?.name||'搭子' }} 的桌边（取消则留给自己）</label><button class="primary" :disabled="busy||!note.trim()">留在桌边<MessageCircle :size="15"/></button></form><div class="desk-notes"><article v-for="n in personalNotes" :key="n.id"><span>{{ state.players[n.from]?.name }} → {{ state.players[n.to]?.name }} · {{ date(n.at) }}</span><p>{{ n.text }}</p><button class="text-button" :disabled="busy" @click="perform('living_note_remove',{id:n.id})">{{ n.from===player.id?'撤回这张便签':'把便签收好' }}</button></article></div>
  <form class="v8-form gift-form" @submit.prevent="perform('living_gift',{option:gift,note:giftNote});giftNote=''"><label>给搭子的小心意<select v-model="gift"><option v-for="g in content.living.gifts" :key="g.id" :value="g.id">{{ g.name }} · {{ g.cost }} 经费</option></select></label><label>附一句话<input v-model="giftNote" maxlength="120" placeholder="不用现在回复，晚点再看。"/></label><button class="primary" :disabled="busy||!partner||player.funds<(content.living.gifts.find(g=>g.id===gift)?.cost||0)"><Gift :size="16"/>放到 {{ partner?.name||'搭子' }} 桌上</button></form><article v-for="g in incomingGifts" :key="g.id" class="v8-note"><span class="small-label">来自 {{ state.players[g.from]?.name }} · {{ date(g.sentAt) }}</span><h3>{{ g.name }}</h3><p>{{ g.note||'给你留了一点小心意。' }}</p><button class="primary" :disabled="busy" @click="perform('living_gift_open',{id:g.id})">打开这份心意</button></article>
 </template></section></template>
